const [value, setValue] = useState<RichTextValue>([]);

const search = (query: string) =>
  query
    ? [{ id: 'people', heading: 'People', entityType: 'person',
         items: people.filter((p) => p.label.toLowerCase().includes(query.toLowerCase())) }]
    : RECENTS;

<RichTextArea
  aria-label="Note"
  value={value}
  onChange={setValue}
  onSearch={search}
  rows={3}
/>

const entityConfig = {
  person: { tone: 'blue', icon: <PersonIcon decorative /> },
  matter: { tone: 'teal', icon: <FolderIcon decorative /> },
  roadmap: { tone: 'purple', icon: <RoadmapIcon decorative /> },
};

<RichTextArea
  aria-label="Note"
  value={value}
  onChange={setValue}
  onSearch={search}
  entityConfig={entityConfig}
/>

const stored: RichTextValue = [
  { type: 'text', text: 'Ask ' },
  { type: 'entity', entity: { id: 'p1', entityType: 'person', label: 'Ben Averill', href: '/people/p1' } },
  { type: 'text', text: ' about the filing' },
];

<RichTextArea aria-label="Note" value={stored} onChange={setValue} onSearch={search} />

const section = {
  id: 'people', heading: 'People', entityType: 'person',
  items: [{
    id: 'p1', entityType: 'person', label: 'Ben Averill', href: '/people/p1',
    leadingElement: <Avatar size="xs" name="Ben Averill" />,
  }],
};

<RichTextArea aria-label="Note" value={value} onChange={setValue} onSearch={() => [section]} />
